package ratelimit

import (
	"sync"
	"testing"
	"time"
)

type fakeClock struct {
	mu sync.Mutex
	t  time.Time
}

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.t
}

func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.t = c.t.Add(d)
}

func TestNewValidation(t *testing.T) {
	fc := &fakeClock{t: time.Unix(0, 0)}
	tests := []struct {
		name    string
		cap     float64
		refill  float64
		clock   Clock
		wantErr bool
	}{
		{"ok", 10, 1, fc, false},
		{"zero capacity", 0, 1, fc, true},
		{"negative capacity", -1, 1, fc, true},
		{"zero refill", 10, 0, fc, true},
		{"negative refill", 10, -1, fc, true},
		{"nil clock", 10, 1, nil, true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			_, err := New(tt.cap, tt.refill, tt.clock)
			if (err != nil) != tt.wantErr {
				t.Fatalf("err=%v wantErr=%v", err, tt.wantErr)
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	base := time.Unix(0, 0)
	tests := []struct {
		name    string
		cap     float64
		refill  float64
		advances []time.Duration
		n       int
		want    bool
	}{
		{"first allow", 5, 1, nil, 5, true},
		{"exceeds capacity", 5, 1, nil, 6, false},
		{"zero n", 5, 1, nil, 0, true},
		{"negative n", 5, 1, nil, -1, true},
		{"refill half", 10, 2, []time.Duration{5 * time.Second}, 10, true},
		{"refill not enough", 10, 1, []time.Duration{3 * time.Second}, 10, false},
		{"refill capped", 10, 100, []time.Duration{10 * time.Second}, 10, true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			fc := &fakeClock{t: base}
			l, _ := New(tt.cap, tt.refill, fc)
			for _, d := range tt.advances {
				fc.Advance(d)
			}
			got := l.AllowN(tt.n)
			if got != tt.want {
				t.Fatalf("AllowN(%d)=%v want %v", tt.n, got, tt.want)
			}
		})
	}
}

func TestSequentialDrain(t *testing.T) {
	fc := &fakeClock{t: base}
	l, _ := New(3, 1, fc)
	for i := 0; i < 3; i++ {
		if !l.AllowN(1) {
			t.Fatalf("call %d should be allowed", i)
		}
	}
	if l.AllowN(1) {
		t.Fatal("4th call should be denied")
	}
	fc.Advance(1 * time.Second)
	if !l.AllowN(1) {
		t.Fatal("after 1s refill should allow")
	}
}

func TestConcurrent(t *testing.T) {
	fc := &fakeClock{t: base}
	l, _ := New(100, 100, fc)
	var wg sync.WaitGroup
	allowed := make(chan bool, 200)
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			allowed <- l.AllowN(1)
		}()
	}
	wg.Wait()
	close(allowed)
	count := 0
	for a := range allowed {
		if a {
			count++
		}
	}
	if count != 100 {
		t.Fatalf("expected 100 allowed, got %d", count)
	}
}
